from pathlib import Path
import re, json, collections
pdbs=sorted(Path('/saisdata/37').glob('target*.pdb'))
for path in pdbs:
    serial=path.stem
    header={'pdb_id':None,'classification':None,'date':None,'title':'','keywords':'','resolution':None,'compounds':[], 'sources':[], 'dbrefs':set(), 'uniprot':set(), 'het_counts':collections.Counter(), 'het_chains':collections.defaultdict(set), 'chains':collections.Counter(), 'atoms':0, 'hetatoms':0, 'models':0}
    with path.open('rt', errors='ignore') as fh:
        for line in fh:
            rec=line[:6].strip()
            if rec=='HEADER':
                header['classification']=line[10:50].strip() or None
                header['date']=line[50:59].strip() or None
                header['pdb_id']=line[62:66].strip() or None
            elif rec=='TITLE':
                header['title'] += ' ' + line[10:80].strip()
            elif rec=='KEYWDS':
                header['keywords'] += ' ' + line[10:80].strip()
            elif rec=='EXPDTA':
                header['experimental']=line[10:80].strip()
            elif rec=='REMARK' and line[7:10].strip()=='2' and 'RESOLUTION.' in line:
                m=re.search(r'RESOLUTION\\.\\s+([0-9.]+)\\s+ANGSTROMS', line)
                if m: header['resolution']=float(m.group(1))
            elif rec=='COMPND' and any(k in line for k in ['MOLECULE:', 'EC:', 'CHAIN:']):
                txt=line[10:80].strip().rstrip(';')
                if txt: header['compounds'].append(txt)
            elif rec=='SOURCE' and any(k in line for k in ['ORGANISM_SCIENTIFIC:', 'EXPRESSION_SYSTEM:']):
                txt=line[10:80].strip().rstrip(';')
                if txt: header['sources'].append(txt)
            elif rec=='DBREF':
                parts=line.split()
                if len(parts)>=7:
                    header['dbrefs'].add(parts[6])
                    if parts[5] in ('UNP','SWS','TREMBL') or len(parts[6])>=6:
                        header['uniprot'].add(parts[6])
            elif rec=='ATOM':
                header['atoms']+=1
                chain=line[21].strip() or '_'
                header['chains'][chain]+=1
            elif rec=='HETATM':
                header['hetatoms']+=1
                res=line[17:20].strip()
                chain=line[21].strip() or '_'
                if res not in {'HOH','WAT','DOD'}:
                    header['het_counts'][res]+=1
                    header['het_chains'][res].add(chain)
            elif rec=='MODEL':
                header['models']+=1
    # compact, derived only
    print(json.dumps({
        'target': serial,
        'pdb_id': header['pdb_id'],
        'classification': header['classification'],
        'deposition_date': header['date'],
        'experimental': header.get('experimental'),
        'resolution_A': header['resolution'],
        'title': ' '.join(header['title'].split())[:220],
        'keywords': ' '.join(header['keywords'].split())[:180],
        'compounds': header['compounds'][:8],
        'sources': header['sources'][:6],
        'dbrefs': sorted(header['dbrefs'])[:8],
        'uniprot': sorted(header['uniprot'])[:8],
        'polymer_chains': dict(header['chains']),
        'atom_count': header['atoms'],
        'hetatom_count': header['hetatoms'],
        'nonwater_hets': [{'code':k,'atoms':v,'chains':sorted(header['het_chains'][k])} for k,v in header['het_counts'].most_common(20)],
        'models': header['models'] or 1,
    }, sort_keys=True))
PY"

