from pathlib import Path
from collections import OrderedDict
import json, urllib.request, urllib.parse, urllib.error, time
AA={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','SEC':'U','PYL':'O'}
def seq_for(path):
    residues=OrderedDict()
    for line in path.open(errors='ignore'):
        if line.startswith('ATOM'):
            key=(line[21].strip() or '_', line[22:26].strip(), line[26].strip())
            residues.setdefault(key, line[17:20].strip())
    return ''.join(AA.get(r,'X') for r in residues.values())

def post_json(url,payload):
    data=json.dumps(payload).encode()
    req=urllib.request.Request(url,data=data,headers={'Content-Type':'application/json','User-Agent':'targetmol-agent/1.0'})
    with urllib.request.urlopen(req,timeout=30) as resp:
        return json.loads(resp.read().decode())

url='https://search.rcsb.org/rcsbsearch/v2/query'
for path in sorted(Path('/saisdata/37').glob('target*.pdb')):
    seq=seq_for(path)
    payload={
        'query': {'type':'terminal','service':'sequence','parameters':{'evalue_cutoff':1e-6,'identity_cutoff':0.9,'sequence_type':'protein','value':seq}},
        'return_type':'polymer_entity',
        'request_options': {'paginate': {'start':0,'rows':10}, 'results_content_type':['experimental']}
    }
    try:
        data=post_json(url,payload)
        rows=[]
        for r in data.get('result_set',[])[:8]:
            rows.append({'identifier':r.get('identifier'), 'score':r.get('score'), 'services':r.get('services')})
        print(json.dumps({'target':path.stem,'seq_len':len(seq),'hit_count':data.get('total_count'), 'hits':rows}, sort_keys=True))
    except Exception as e:
        print(json.dumps({'target':path.stem,'error':type(e).__name__, 'message':str(e)[:180]}, sort_keys=True))
PY"

