import json, urllib.request
entry_ids=['4HW2','4HW3','4HW4','4ZBF','4ZBI','5W89','3ZON','4OLI','4WOV','5C01','5C03','5TKD','7XZ5','7XZ6','8VHF','8ZR5','8ZRK','9L79']
query='''query("'$ids:[String!]!){
  entries(entry_ids:$ids){
    rcsb_id
    struct { title }
    rcsb_entry_info { resolution_combined polymer_entity_count nonpolymer_entity_count }
    exptl { method }
    polymer_entities { rcsb_polymer_entity { pdbx_description } rcsb_polymer_entity_container_identifiers { entity_id asym_ids auth_asym_ids uniprot_ids } }
    nonpolymer_entities { rcsb_nonpolymer_entity_container_identifiers { entity_id nonpolymer_comp_id auth_asym_ids } rcsb_nonpolymer_entity { pdbx_description } }
  }
}'"'''
req=urllib.request.Request('https://data.rcsb.org/graphql',data=json.dumps({'query':query,'variables':{'ids':entry_ids}}).encode(),headers={'Content-Type':'application/json','User-Agent':'targetmol-agent/1.0'})
with urllib.request.urlopen(req,timeout=45) as resp:
    data=json.loads(resp.read().decode())
if data.get('errors'):
    print(json.dumps({'errors':data['errors'][:2]}, sort_keys=True))
entries=data.get('data',{}).get('entries') or []
for e in entries:
    if not e: continue
    lig=[]
    for n in e.get('nonpolymer_entities') or []:
        cid=((n.get('rcsb_nonpolymer_entity_container_identifiers') or {}).get('nonpolymer_comp_id'))
        desc=((n.get('rcsb_nonpolymer_entity') or {}).get('pdbx_description'))
        if cid not in ('HOH','DOD','WAT'):
            lig.append({'code':cid,'description':desc})
    polys=[]
    for p in e.get('polymer_entities') or []:
        ident=p.get('rcsb_polymer_entity_container_identifiers') or {}
        polys.append({'entity':ident.get('entity_id'),'desc':(p.get('rcsb_polymer_entity') or {}).get('pdbx_description'), 'uniprot':ident.get('uniprot_ids'), 'auth_asym':ident.get('auth_asym_ids')})
    print(json.dumps({'id':e.get('rcsb_id'),'title':(e.get('struct') or {}).get('title'),'method': [x.get('method') for x in e.get('exptl') or []], 'resolution':(e.get('rcsb_entry_info') or {}).get('resolution_combined'), 'polymers':polys[:3], 'ligands':lig[:10]}, sort_keys=True))
PY"

